package com.bank.pkgen.model;

import jakarta.persistence.*;
import java.math.BigDecimal;

@Entity
@Table(name = "identity_trades")
public class IdentityTrade {
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;  // IDENTITY: DB auto-increment. DISABLES batch inserts!

    private String symbol;
    private BigDecimal amount;

    protected IdentityTrade() {}
    public IdentityTrade(String symbol, BigDecimal amount) {
        this.symbol = symbol; this.amount = amount;
    }
    public Long getId() { return id; }
    public String getSymbol() { return symbol; }
}
