// ─── File: src/test/java/com/bank/pkgen/PkGenerationTest.java ───
package com.bank.pkgen;

import org.junit.jupiter.api.Test;
import static org.assertj.core.api.Assertions.*;

class PkGenerationTest {

    @Test
    void identityDisablesBatchInserts() {
        // IDENTITY: Hibernate must flush EACH insert to get the auto-generated ID.
        // hibernate.jdbc.batch_size=50 is IGNORED for IDENTITY strategy!
        // Because: Hibernate needs the ID immediately → can't defer the INSERT.
        // 10,000 inserts: 10,000 individual INSERTs → slow!
        assertThat(true).isTrue();
    }

    @Test
    void sequenceEnablesBatchInserts() {
        // SEQUENCE with allocationSize=50:
        // Hibernate calls: SELECT nextval('seq') → gets range 1-50
        // Assigns IDs locally: entity1.id=1, entity2.id=2, ... entity50.id=50
        // Batch-INSERTs all 50 in ONE JDBC call!
        // Next batch: SELECT nextval('seq') → gets range 51-100
        // 10,000 inserts: 200 sequence calls + 200 batch INSERTs → 10x faster!
        int total = 10000;
        int allocationSize = 50;
        int sequenceCalls = total / allocationSize;
        assertThat(sequenceCalls).isEqualTo(200);  // only 200 DB round-trips for IDs!
    }

    @Test
    void uuidNoDbRoundTrip() {
        // UUID generated in JVM — NO database call needed for ID!
        // Batch-friendly: IDs already assigned before INSERT.
        // But: 16 bytes vs 8 bytes (bigint) → larger indexes.
        // Random UUID v4 → scattered B-tree inserts → page splits → fragmentation.
        // Fix: UUIDv7 (time-ordered) → sequential inserts → healthy B-tree.
        java.util.UUID uuid = java.util.UUID.randomUUID();
        assertThat(uuid.toString()).hasSize(36);  // 32 hex + 4 dashes
    }

    @Test
    void autoIsProviderDependent() {
        // AUTO: Hibernate picks strategy based on database:
        // PostgreSQL → SEQUENCE (has native sequences)
        // MySQL pre-8.0 → TABLE or IDENTITY
        // MySQL 8.0+ → SEQUENCE (added native sequences)
        // (Caution) Behavior may change between Hibernate versions!
        // RECOMMENDATION: always be EXPLICIT — use SEQUENCE or IDENTITY.
        assertThat(true).isTrue();
    }

    @Test
    void allocationSizeMustMatchSequenceIncrement() {
        // allocationSize=50 on @SequenceGenerator
        // MUST match: CREATE SEQUENCE seq INCREMENT 50
        // If mismatched: Hibernate thinks it has 50 IDs but sequence only gave 1
        // → duplicate key violations in production!
        int allocationSize = 50;
        int sequenceIncrement = 50;
        assertThat(allocationSize).isEqualTo(sequenceIncrement);
    }
}
